/**
 * Upserts the supplied piles + words for the signed-in user (server is
the merge winner on conflict — local entries with a newer updatedAt
replace the server row, otherwise the server row stays). Returns the
full merged state.

 * @summary Bootstrap sync — upload local snapshot and receive merged state
 */
export const syncWordpileBodyPilesItemBuildVotesStackerMin = 0;

export const syncWordpileBodyPilesItemBuildVotesBlocksMin = 0;

export const syncWordpileBodyPilesItemBuildVotesPlanksMin = 0;

export const SyncWordpileBody = zod.object({
  piles: zod.array(
    zod.object({
      id: zod.string().uuid(),
      name: zod.string(),
      createdAt: zod.coerce.date(),
      updatedAt: zod.coerce.date(),
      words: zod.array(
        zod.object({
          id: zod.string().uuid(),
          pileId: zod.string().uuid(),
          word: zod.string(),
          note: zod.string(),
          bucket: zod.enum(["unsorted", "load", "interior", "avoid"]),
          saferAlternative: zod.string(),
          createdAt: zod.coerce.date(),
          updatedAt: zod.coerce.date(),
        }),
      ),
      buildVotes: zod
        .object({
          stacker: zod
            .number()
            .min(syncWordpileBodyPilesItemBuildVotesStackerMin),
          blocks: zod
            .number()
            .min(syncWordpileBodyPilesItemBuildVotesBlocksMin),
          planks: zod
            .number()
            .min(syncWordpileBodyPilesItemBuildVotesPlanksMin),
          lastChoice: zod
            .union([
              zod.literal("stacker"),
              zod.literal("blocks"),
              zod.literal("planks"),
              zod.literal(null),
            ])
            .nullable(),
          updatedAt: zod.coerce.date(),
        })
        .optional(),
    }),
  ),
});

